async (cursor, num, params) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pageStart = Date.now();
  const SEND = '.ds-button--primary.ds-button--filled.ds-button--circle';
  const answers = () => [...document.querySelectorAll('.ds-assistant-message-main-content')];
  const busy = () => { const b = document.querySelector(SEND); return !!(b && window.__dsIdle && b.innerHTML !== window.__dsIdle); };
  if (!cursor) {
    let ta = null;
    for (let i = 0; i < 30 && !(ta = document.querySelector('textarea')); i++) await sleep(300);
    if (!ta) throw new Error('[deepseek-chat] 没找到输入框 textarea url=' + location.pathname);
    if (answers().length) throw new Error('[deepseek-chat] 入口页上已经有回复——这不是一条新对话');
    const setValue = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
    setValue.call(ta, params.prompt);
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    await sleep(500);
    const send = document.querySelector(SEND);
    if (!send) throw new Error('[deepseek-chat] 没找到发送按钮 ' + SEND);
    if (send.getAttribute('aria-disabled') === 'true') throw new Error('[deepseek-chat] 写入提示词后发送按钮仍是禁用（输入框字数 ' + ta.value.length + '）');
    window.__dsIdle = send.innerHTML;
    send.click();
    await sleep(1500);
    window.__dsT0 = Date.now();
  }
  const deadline = Math.min(Date.now() + 22000, pageStart + 26000);
  let lastText = null, since = 0;
  while (Date.now() < deadline) {
    const a = answers().at(-1);
    const txt = a ? (a.innerText || '').trim() : '';
    if (/^服务器繁忙|请稍后重试。?$/.test(txt)) throw new Error('[deepseek-chat] DeepSeek 回了：' + txt.slice(0, 100));
    if (a && !busy() && txt) {
      if (txt === lastText) {
        if (Date.now() - since > 1500) {
          const id = (location.pathname.match(/\/s\/([\w-]+)/) || [])[1] || ('m' + Date.now());
          return { items: [{ guid: id, text: txt, url: location.href }], cursor: '' };
        }
      } else { lastText = txt; since = Date.now(); }
    }
    await sleep(500);
  }
  const elapsed = Date.now() - (window.__dsT0 || pageStart);
  if (!busy() && !answers().length && elapsed > 30000) {
    const lines = document.body.innerText.trim().split('\n').filter(Boolean);
    throw new Error('[deepseek-chat] 发出 ' + Math.round(elapsed / 1000) + 's 后既没在生成、也没有回复 url=' + location.pathname + ' 页面末尾: ' + lines.slice(-4).join(' / ').slice(0, 300));
  }
  if (elapsed > 300000) throw new Error('[deepseek-chat] 300s 内没等到完整回复');
  return { items: [], pending: true, cursor: String(Number(cursor || 0) + 1) };
}
